import re,glob,json
cls={}  # file->classes
allc={}
for f in glob.glob('src/**/*.ts',recursive=True):
    t=open(f).read()
    for m in re.finditer(r'@Component[\s\S]*?export class (\w+)',t):
        cls.setdefault(f,[]).append(m.group(1)); allc[m.group(1)]=f
# html files -> ts
def owner(f):
    if f.endswith('.html'): f=f[:-5]+'.ts'
    return cls.get(f,[None])[0]
edges={}
cur=None
S='/private/tmp/claude-502/-private-var-folders-tb-68tnh0pn5619ks87wpp1gqmc0000gp-T-ng-facts-atlas-blast-tool-mIpqI2-workspace/e4592041-af28-47c0-bf17-ffbfc6dee5d3/scratchpad/all.txt'
for l in open(S):
    m=re.match(r'^(\w+) <',l)
    if m: cur=m.group(1); continue
    m=re.match(r'\s+(\S+?):\d+',l)
    if m:
        o=owner(m.group(1))
        if not o: print('noowner',l)
        else: edges.setdefault(o,set()).add(cur)
# routes
roots={};  # class -> paths
def walk(rs,prefix):
    pass
for f in glob.glob('src/app/provinces/*/*.routes.ts'):
    prov=f.split('/')[3]
    t=open(f).read()
    for m in re.finditer(r'path: "([^"]*)", (?:component: (\w+)|loadComponent[^\n]*?module\.(\w+))(?:, children: \[(.*?)\] \})?',t):
        p,c1,c2,ch=m.groups()
        roots.setdefault(c1 or c2,[]).append(f'{prov}/{p}')
        if ch:
            for n in re.finditer(r'path: "([^"]*)", component: (\w+)',ch):
                roots.setdefault(n.group(2),[]).append(f'{prov}/{p}/{n.group(1)}')
                edges.setdefault(c1 or c2,set()).add(n.group(2))  # child shown inside outlet
def reach(c,seen):
    if c in seen: return
    seen.add(c)
    for d in edges.get(c,()): reach(d,seen)
res={}
for r,ps in roots.items():
    s=set(); reach(r,s)
    for t in ('TentComponent','RationComponent','HelmetComponent'):
        if t in s: res.setdefault(t,[]).extend(ps)
seen=set()
for r in roots: reach(r,seen)
seen.add('AppComponent')
unr=sorted(set(allc)-seen)
out={'tentRoutes':sorted(set(res['TentComponent'])),'rationRoutes':sorted(set(res.get('RationComponent',[]))),'helmetRoutes':sorted(set(res['HelmetComponent'])),'unroutedComponents':unr}
json.dump(out,open('answers.json','w'),indent=1)
print(json.dumps(out,indent=1)); print(len(allc), [c for c in roots if c not in allc])
EOF
